/// One fault from a multi-byte read: the byte that began the sequence the
/// codec could not finish, where it stood, and why the reference names it.
pub struct CodecFault {
    pub at: usize,
    pub byte: u8,
    pub reason: &'static str,
}

fn paired(keys: &'static str, values: &'static str) -> Vec<(u16, char)> {
    let mut table = Vec::new();
    let mut letters = values.chars();
    let mut at = 0;
    while at + 4 <= keys.len() {
        if let (Ok(code), Some(letter)) = (u16::from_str_radix(&keys[at..at + 4], 16), letters.next()) {
            table.push((code, letter));
        }
        at += 4;
    }
    table
}

fn seek(table: &[(u16, char)], code: u16) -> Option<char> {
    table.binary_search_by_key(&code, |held| held.0).ok().map(|place| table[place].1)
}

static CP949_TABLE: OnceLock<Vec<(u16, char)>> = OnceLock::new();
static CP932_TABLE: OnceLock<Vec<(u16, char)>> = OnceLock::new();
static SHIFT_JIS_TABLE: OnceLock<Vec<(u16, char)>> = OnceLock::new();

fn katakana(byte: u8) -> char {
    char::from_u32(0xFF61 + u32::from(byte - 0xA1)).unwrap_or('\u{fffd}')
}

/// How a run of bytes is read by one of the three multi-byte pages. A
/// byte below 128 stands for itself; the two Japanese pages give the
/// half-width katakana range a letter of its own, and CP932 gives four
/// lone bytes one apiece; any other byte above 127 begins a two-byte
/// sequence the table must hold, else the reference's own fault is
/// returned with the byte that began it.
fn decode_page(bytes: &[u8], table: &[(u16, char)], japanese: bool, cp932: bool) -> Result<String, CodecFault> {
    let mut told = String::new();
    let mut at = 0;
    while at < bytes.len() {
        let byte = bytes[at];
        if byte < 0x80 {
            told.push(char::from(byte));
            at += 1;
            continue;
        }
        if japanese && (0xA1..=0xDF).contains(&byte) {
            told.push(katakana(byte));
            at += 1;
            continue;
        }
        if cp932 {
            match byte {
                0x80 => { told.push('\u{80}'); at += 1; continue; }
                0xA0 => { told.push('\u{f8f0}'); at += 1; continue; }
                0xFD => { told.push('\u{f8f1}'); at += 1; continue; }
                0xFE => { told.push('\u{f8f2}'); at += 1; continue; }
                0xFF => { told.push('\u{f8f3}'); at += 1; continue; }
                _ => {}
            }
        }
        match bytes.get(at + 1) {
            None => return Err(CodecFault { at, byte, reason: "incomplete multibyte sequence" }),
            Some(&trail) => match seek(table, (u16::from(byte) << 8) | u16::from(trail)) {
                Some(letter) => { told.push(letter); at += 2; }
                None => return Err(CodecFault { at, byte, reason: "illegal multibyte sequence" }),
            },
        }
    }
    Ok(told)
}

pub fn decode_cp949(bytes: &[u8]) -> Result<String, CodecFault> {
    let table = CP949_TABLE.get_or_init(|| paired(CP949_KEYS, CP949_VALUES));
    decode_page(bytes, table, false, false)
}

pub fn decode_cp932(bytes: &[u8]) -> Result<String, CodecFault> {
    let table = CP932_TABLE.get_or_init(|| paired(CP932_KEYS, CP932_VALUES));
    decode_page(bytes, table, true, true)
}

pub fn decode_shift_jis(bytes: &[u8]) -> Result<String, CodecFault> {
    let table = SHIFT_JIS_TABLE.get_or_init(|| paired(SHIFT_JIS_KEYS, SHIFT_JIS_VALUES));
    decode_page(bytes, table, true, false)
}
